using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for the given query.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The search query to send to the external API.")] string query,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"data?q={Uri.EscapeDataString(query)}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Desired summary style (brief, detailed, bullet-points).")] string style = "brief")
    {
        return
        [
            new McpServerPromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"Please provide a {style} summary of the following text:\n\n{content}"
                }
            }
        ];
    }
}

